package io.github.jhipster.sample.web.rest;

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;

@Controller
public class ClientForwardController {

    /**
     * Forwards any unmapped paths (except those containing a period) to the client {@code index.html}.
     * <p>
     * Spring 6 uses the {@code PathPatternParser} by default, which does not allow {@code **} in the middle of a pattern
     * (like the former {@code /**}{@code /{path:[^\\.]*}}). The client routes are therefore matched explicitly, segment by
     * segment, with patterns that are valid for both the {@code PathPatternParser} and the {@code AntPathMatcher}.
     *
     * @return forward to client {@code index.html}.
     */
    @GetMapping(
        value = {
            "/{path:[^\\.]*}",
            "/*/{path:[^\\.]*}",
            "/*/*/{path:[^\\.]*}",
            "/*/*/*/{path:[^\\.]*}",
            "/*/*/*/*/{path:[^\\.]*}",
            "/*/*/*/*/*/{path:[^\\.]*}",
            "/*/*/*/*/*/*/{path:[^\\.]*}",
            "/*/*/*/*/*/*/*/{path:[^\\.]*}",
        }
    )
    public String forward() {
        return "forward:/";
    }
}

